const dialog=document.getElementById('evidence-dialog'),img=document.getElementById('evidence-large-image'),viewport=document.getElementById('evidence-viewport');let zoom=1,trigger=null;
function fit(){if(!img.naturalWidth)return;const w=Math.min(img.naturalWidth,Math.max(120,viewport.clientWidth-30),Math.max(120,viewport.clientHeight-30)*img.naturalWidth/img.naturalHeight);img.style.width=Math.round(w*zoom)+'px';document.getElementById('evidence-zoom').textContent=Math.round(zoom*100)+'%';}
for(const b of document.querySelectorAll('[data-evidence-image]'))b.addEventListener('click',()=>{trigger=b;zoom=1;img.src=b.dataset.evidenceImage;img.alt=b.dataset.caption;document.getElementById('evidence-caption').textContent=b.dataset.caption;dialog.showModal();if(img.complete)fit();});
img.addEventListener('load',fit);document.getElementById('evidence-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>trigger?.focus());
document.getElementById('evidence-plus').addEventListener('click',()=>{zoom=Math.min(4,zoom+.25);fit();});document.getElementById('evidence-minus').addEventListener('click',()=>{zoom=Math.max(.5,zoom-.25);fit();});document.getElementById('evidence-fit').addEventListener('click',()=>{zoom=1;fit();});new ResizeObserver(fit).observe(viewport);
